  function loading(show,text){const box=document.getElementById('loading'),label=document.getElementById('loadingText');if(label&&text)label.textContent=text;if(box)box.classList.toggle('show',!!show);}
  function message(text,type=''){const el=document.getElementById('message');if(!el)return;el.textContent=text||'';el.className=`message${text?' show':''}${type?` ${type}`:''}`;}
  function editor(){return{wrap:document.getElementById('editor'),title:document.getElementById('editorTitle'),sub:document.getElementById('editorSub'),body:document.getElementById('editorBody'),error:document.getElementById('formError')};}
